import heapq
import itertools


class Helpdesk:
    PRIORITIES = ("normal", "high", "critical")

    def __init__(self) -> None:
        self._customers = {}
        self._tickets = {}
        self._queue = []
        self._ticket_ids = itertools.count(1)
        self._sequence = itertools.count()

    def add_customer(self, name: str, vip: bool = False) -> None:
        self._customers[name] = vip
        # Rebuild so that changes to a customer's VIP status affect
        # tickets already waiting in the queue.
        self._queue = [
            self._queue_entry(ticket_id, ticket)
            for ticket_id, ticket in self._tickets.items()
            if ticket["status"] == "queued"
        ]
        heapq.heapify(self._queue)

    def _queue_entry(self, ticket_id, ticket):
        return (
            not self._customers[ticket["customer"]],
            -self.PRIORITIES.index(ticket["priority"]),
            ticket["sequence"],
            ticket_id,
        )

    def open_ticket(
        self, customer: str, title: str, priority: str = "normal"
    ) -> int:
        if not title:
            raise ValueError("Ticket title cannot be empty")
        if priority not in self.PRIORITIES:
            raise ValueError("Invalid priority")
        if customer not in self._customers:
            raise KeyError(customer)

        ticket_id = next(self._ticket_ids)
        ticket = {
            "customer": customer,
            "title": title,
            "priority": priority,
            "status": "queued",
            "sequence": next(self._sequence),
        }
        self._tickets[ticket_id] = ticket
        heapq.heappush(self._queue, self._queue_entry(ticket_id, ticket))
        return ticket_id

    def next_ticket(self) -> int | None:
        while self._queue:
            _, _, _, ticket_id = heapq.heappop(self._queue)
            ticket = self._tickets[ticket_id]
            if ticket["status"] == "queued":
                ticket["status"] = "in_progress"
                return ticket_id
        return None

    def close(self, ticket_id: int) -> None:
        self._tickets[ticket_id]["status"] = "closed"

    def reopen(self, ticket_id: int) -> None:
        ticket = self._tickets[ticket_id]
        if ticket["status"] == "closed":
            raise ValueError("A closed ticket cannot be reopened")
        if ticket["status"] == "queued":
            return

        ticket["status"] = "queued"
        ticket["sequence"] = next(self._sequence)
        heapq.heappush(self._queue, self._queue_entry(ticket_id, ticket))
